// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 newVal) public {
        // Any value is admissible; initialization is part of the scenario.
        c.Initialized();

        vm.prank(address(0xA11CE));
        bool ok;
        try c.SetMinSum(newVal) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: once initialized, SetMinSum always reverts and MinSum stays untouched.
        assertTrue(!ok && c.MinSum() == 0);
    }
}
